DELETE ar FROM dbo.CHECKINOUT_ATTENDANCE_RECORD ar INNER JOIN dbo.CHECKINOUT_EMPLOYEE e ON e.CHECKINOUT_EMPLOYEE_ID = ar.CHECKINOUT_EMPLOYEE_ID WHERE e.EMPLOYEE_CODE IN (N'김도완', N'sm.park@bnow.co.kr', N'contact@bnow.co.kr', N'su.lee@bnow.co.kr', N'mk.chae@bnow.co.kr', N'ch.choi@bnow.co.kr', N'elon.choo@bnow.co.kr') AND ar.RECORDED_AT < CAST('2026-07-22 00:00:00' AS datetime2(0));

INSERT INTO dbo.CHECKINOUT_ATTENDANCE_RECORD (
    CHECKINOUT_EMPLOYEE_ID, RECORD_TYPE, RECORDED_AT, RECORD_METHOD, IS_VERIFIED, CREATED_AT
)
SELECT
    e.CHECKINOUT_EMPLOYEE_ID,
    'IN',
    CAST('2025-02-20 09:18:00' AS datetime2(0)),
    N'PC',
    0,
    CAST('2025-02-20 09:18:00' AS datetime2(0))
FROM dbo.CHECKINOUT_EMPLOYEE e
WHERE e.EMPLOYEE_CODE = N'su.lee@bnow.co.kr';

